namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new(_nextId++, "Welcome to the notifications page!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates new notifications arriving over time (roughly 1 every 8-15 s).</summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.Next(0, 3) != 0) return; // ~1-in-3 chance per call

        lock (_lock)
        {
            var messages = new[]
            {
                "Deployment completed for service-api.",
                "CPU alert resolved on node-3.",
                "New comment on your pull request #42.",
                "Scheduled maintenance window starts in 1 hour.",
                "Build #1087 succeeded.",
                "Disk usage warning on db-primary.",
            };

            _notifications.Add(new(
                _nextId++,
                messages[Random.Shared.Next(messages.Length)],
                DateTime.UtcNow));
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@inject PersistentComponentState PersistentState
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span style="background:#0d6efd;color:#fff;border-radius:999px;padding:2px 10px;font-size:0.6em;vertical-align:middle;">
        @_notifications.Count
    </span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul>
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li>
                <strong>@n.Timestamp.ToString("HH:mm:ss")</strong> &mdash; @n.Message
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistSub;
    private int _lastSeenId;

    protected override void OnInitialized()
    {
        // During SSR this persists the data so the interactive runtime can reuse it.
        _persistSub = PersistentState.RegisterOnPersisting(PersistNotifications);

        // Try to restore state that was persisted during SSR.
        if (PersistentState.TryTakeFromJson<List<Notification>>(
                "notifications", out var restored) && restored is not null)
        {
            _notifications = restored;
        }
        else
        {
            // First render (SSR): load from service.
            _notifications = Svc.GetAll();
        }

        _lastSeenId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Now interactive — start the polling loop.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            Svc.SimulateIncoming();

            var newer = Svc.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastSeenId = newer.Max(n => n.Id);

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    private Task PersistNotifications()
    {
        PersistentState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        _persistSub.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

