namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        _notifications.Add(new(_nextId++, "Welcome to the notifications page!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>Simulates new notifications arriving over time.</summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.Next(0, 3) != 0) return;

        lock (_lock)
        {
            var messages = new[]
            {
                "Deployment completed for service-api.",
                "CPU alert resolved on node-3.",
                "New comment on your pull request #42.",
                "Scheduled maintenance window starts in 1 hour.",
                "Build #1087 succeeded.",
                "Disk usage warning on db-primary.",
            };

            _notifications.Add(new(
                _nextId++,
                messages[Random.Shared.Next(messages.Length)],
                DateTime.UtcNow));
        }
    }
}

